"use client";
import {useEffect,useMemo,useState,type ReactNode,type FormEvent} from "react";
import {LayoutDashboard,Users,Package,ShoppingBag,CalendarDays,ReceiptText,ClipboardList,Store,LogOut,ArrowUpRight,ArrowLeft,Plus,Search,ChevronRight,Check,HelpCircle,Wallet,ShieldCheck,Download,Menu,X,GlassWater,RefreshCw,Eye,FileText} from "lucide-react";
import {D,POLICY,money,sum,statement,creditLine,lateFee,today,monthDate,cutListing,type Credit,type Schedule,type Currency} from "@/lib/finance";
import {legalReference} from "@/lib/legal";
import type {Actor} from "@/lib/actor";

type StoreRow={id:string;name:string;business:string;ruc:string;cut_day:number;pay_day:number;active:boolean};
type ClientRow={id:string;store_id:string;name:string;document:string;phone:string;address:string;currency:Currency;tea:string;credit_limit:string;max_months:number;active:boolean};
type PackageRow={id:string;store_id:string;name:string;detail:string;currency:Currency;amount:string;active:boolean};
type Data={actor:Actor;storeId:string;stores:StoreRow[];clients:ClientRow[];packages:PackageRow[];credits:Credit[];audit:{action:string;entity_id:string;details:Record<string,string>;created_at:string;user_name:string}[]};
type Quote={schedule:Schedule;line:{limit:string;outstanding:string;available:string};lineNow:{available:string};clientName:string;packageName:string;fingerprint:string;legal:ReturnType<typeof legalReference>};
type View="panel"|"clientes"|"paquetes"|"compra"|"cronograma"|"pagos"|"corte"|"portal"|"tiendas";
type ApiError={error:string;field?:string};
const viewNames:Record<View,string>={panel:"Panel general",clientes:"Clientes y condiciones",paquetes:"Paquetes de crédito",compra:"Registrar compra",cronograma:"Cronogramas",pagos:"Registrar pago",corte:"Listado del corte",portal:"Portal del cliente",tiendas:"Administrar tiendas"};
const nav=[{id:"panel",icon:LayoutDashboard,label:"Panel general"},{id:"clientes",icon:Users,label:"Clientes"},{id:"paquetes",icon:Package,label:"Paquetes"},{id:"compra",icon:ShoppingBag,label:"Nueva compra"},{id:"cronograma",icon:CalendarDays,label:"Cronogramas"},{id:"pagos",icon:ReceiptText,label:"Registrar pago"},{id:"corte",icon:ClipboardList,label:"Listado del corte"},{id:"portal",icon:Wallet,label:"Portal del cliente"}] as const;
const fmt=(v:string|number,currency:Currency="PEN")=>(currency==="PEN"?"S/ ":"US$ ")+new Intl.NumberFormat("es-PE",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v));
const rate=(v:string)=>new D(v).mul(100).toFixed(7)+" %";
const num=(v:string|number)=>new Intl.NumberFormat("es-PE",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v));
const teq=(tea:string)=>new D(1).plus(tea).pow(new D(15).div(360)).minus(1).toString();
const ted=(tea:string)=>new D(1).plus(tea).pow(new D(1).div(360)).minus(1).toString();
const date=(s:string|null)=>s?s.split("-").reverse().join("/"):"—";
const shortId=(id:string)=>"VC-"+id.slice(-6).toUpperCase();
const actionLabels:Record<string,string>={INICIAR_SESION:"Inicio de sesión",GUARDAR_CLIENTE:"Cliente guardado",GUARDAR_PAQUETE:"Paquete guardado",GUARDAR_TIENDA:"Tienda guardada",REGISTRAR_CREDITO:"Crédito registrado",REGISTRAR_PAGO:"Pago registrado",CARGAR_DEMOSTRACION:"Carga de datos de demostración"}
const labels:Record<string,string>={PAGADA:"Pagada",VENCIDA:"Vencida",VENCE_HOY:"Vence hoy",POR_VENCER:"Por vencer",GRACIA_TOTAL:"Gracia total",GRACIA_PROGRAMADA:"Gracia programada",NO_ORIGINADO:"No originado"};
async function api<T>(path:string,body?:unknown):Promise<T>{
  const r=await fetch("/api/"+path,{method:body===undefined?"GET":"POST",headers:body===undefined?{}:{"Content-Type":"application/json"},body:body===undefined?undefined:JSON.stringify(body),cache:"no-store"});
  const json=await r.json();if(!r.ok)throw json;return json;
}
function Badge({status}:{status:string}){return <span className={"badge "+status.toLowerCase()}><span/>{labels[status]??status}</span>;}
function Field({label,hint,children,name,error}:{label:string;hint?:string;children:ReactNode;name?:string;error?:ApiError|null}){return <label className={"field "+(name&&error?.field===name?"invalid":"")}><span>{label}{hint&&<HelpCircle size={13} aria-label={hint}><title>{hint}</title></HelpCircle>}</span>{children}{hint&&<small>{hint}</small>}{error&&name&&error.field===name&&<em role="alert">{error.error}</em>}</label>;}
function Notice({error}:{error:ApiError|null}){return error?<div className="notice error" role="alert">{error.error}</div>:null;}
function Empty({children}:{children:ReactNode}){return <div className="empty"><FileText size={32}/><p>{children}</p></div>;}
function Metric({label,value,note,accent=false}:{label:string;value:string;note:string;accent?:boolean}){return <article className={"metric "+(accent?"accent":"")}><span>{label}</span><strong>{value}</strong><small>{note}</small></article>;}
function csvDownload(name:string,headers:string[],rows:(string|number)[][]){
  const encode=(v:string|number)=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
  const blob=new Blob(["\ufeff"+[headers,...rows].map(r=>r.map(encode).join(";")).join("\r\n")],{type:"text/csv;charset=utf-8"});
  const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);
}
export default function Workspace(){
  const [data,setData]=useState<Data|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState<ApiError|null>(null);
  const [view,setView]=useState<View>("panel"),[asOf,setAsOf]=useState("2026-09-26"),[selected,setSelected]=useState(""),[toast,setToast]=useState(""),[mobile,setMobile]=useState(false);
  async function refresh(storeId?:string){try{const d=await api<Data>("bootstrap"+(storeId?"?storeId="+storeId:""));setData(d);setError(null);return d;}catch(e){const err=e as ApiError;if(err.error.includes("Inicie sesión"))setData(null);else setError(err);}finally{setLoading(false);}}
  useEffect(()=>{void refresh();const v=new URLSearchParams(location.search).get("vista");if(v&&v in viewNames)setView(v as View);},[]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(""),6000);return()=>clearTimeout(t);},[toast]);
  function go(v:View,id?:string){setView(v);if(id)setSelected(id);setMobile(false);history.replaceState(null,"","?vista="+v);}
  const store=data?.stores.find(s=>s.id===data.storeId),actor=data?.actor;
  if(loading)return <main className="loading"><div className="brand-icon"><GlassWater/></div><h1>VidraCred</h1><p>Preparando su cuenta corriente…</p></main>;
  if(!data)return <Login onLogin={async()=>{const d=await refresh();if(d)go(d.actor.role==="CLIENTE"?"portal":"panel");}} connectionError={error}/>;
  const safeView=actor?.role==="CLIENTE"?"portal":view;
  return <div className="app-shell">
    {mobile&&<button className="scrim" aria-label="Cerrar navegación" onClick={()=>setMobile(false)}/>}
    <aside className={"sidebar "+(mobile?"open":"")}>
      <a className="brand" href="/" onClick={e=>{e.preventDefault();go("panel");}}><div className="brand-icon"><GlassWater size={25}/></div><span>Vidra<span className="brand-light">Cred</span><small>CUENTA CORRIENTE</small></span></a>
      <div className="store-label">ESPACIO DE TRABAJO</div><div className="store-switch"><Store size={18}/>{actor?.role==="SISTEMA"?<select aria-label="Tienda activa" value={data.storeId} onChange={async e=>{setSelected("");await refresh(e.target.value);}}>{data.stores.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select>:<span>{store?.name}</span>}</div>
      <div className="store-label">{actor?.role==="CLIENTE"?"MI CUENTA":"GESTIÓN FINANCIERA"}</div>
      <nav>{nav.filter(n=>actor?.role!=="CLIENTE"||n.id==="portal").map(n=><button key={n.id} onClick={()=>go(n.id)} className={safeView===n.id?"active":""}><n.icon size={18}/>{n.label}{safeView===n.id&&<ChevronRight size={15}/>}</button>)}{actor?.role==="SISTEMA"&&<button onClick={()=>go("tiendas")} className={safeView==="tiendas"?"active":""}><Store size={18}/>Tiendas</button>}</nav>
      <div className="sidebar-bottom"><div className="local"><span/>Instalación local<small>Datos guardados en PostgreSQL</small></div><div className="user"><span className="avatar">{actor?.name.slice(0,1)}</span><div><strong>{actor?.name}</strong><small>{actor?.role==="CLIENTE"?"Cliente":actor?.role==="SISTEMA"?"Administrador del sistema":"Administrador de tienda"}</small></div><button aria-label="Cerrar sesión" title="Cerrar sesión" onClick={async()=>{await api("auth/logout",{});setData(null);}}><LogOut size={17}/></button></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-toggle" aria-label="Abrir navegación" onClick={()=>setMobile(true)}><Menu size={20}/></button><span>VidraCred</span><ChevronRight size={14}/><strong>{viewNames[safeView]}</strong></div><div className="date-control"><CalendarDays size={15}/><label htmlFor="asof">Consultar al</label><input id="asof" type="date" value={asOf} max={today()} min="1900-01-01" onChange={e=>{if(e.target.value&&e.target.validity.valid)setAsOf(e.target.value);}}/><button onClick={()=>setAsOf(today())}>Hoy</button></div></header>
      <main><Notice error={error}/>{asOf!==today()&&<div className="historical"><span><Eye size={14}/> Fecha de consulta · {date(asOf)}</span><small>Saldos y pagos se muestran tal como estaban ese día. Use «Hoy» para ver la fecha actual.</small></div>}
        {safeView==="panel"&&<Dashboard data={data} asOf={asOf} go={go}/>}
        {safeView==="clientes"&&<Clients data={data} asOf={asOf} refresh={()=>refresh(data.storeId)} notify={setToast} go={go}/>}
        {safeView==="paquetes"&&<Packages data={data} refresh={()=>refresh(data.storeId)} notify={setToast}/>}
        {safeView==="compra"&&<Purchase key={data.storeId} data={data} store={store!} onDone={async id=>{await refresh(data.storeId);setToast("Crédito registrado. Las condiciones y el cronograma quedaron guardados.");go("cronograma",id);}}/>}
        {safeView==="cronograma"&&<Schedules data={data} asOf={asOf} selected={selected} setSelected={setSelected} go={go}/>}
        {safeView==="pagos"&&<PaymentView data={data} selected={selected} setSelected={setSelected} onDone={async paid=>{await refresh(data.storeId);setAsOf(paid);setToast("Pago registrado. La deuda y la línea disponible se actualizaron.");}}/>}
        {safeView==="corte"&&<CutView data={data} asOf={asOf} store={store!} go={go}/>}
        {safeView==="portal"&&<Portal data={data} asOf={asOf}/>}
        {safeView==="tiendas"&&<Stores data={data} refresh={()=>refresh(data.storeId)} notify={setToast}/>}
      </main><footer><span>VidraCred · Finanzas e Ingeniería Económica</span><span>Base 360 · Quincenas comerciales de 15 días · Política VC-2026.1</span></footer>
    </div>{toast&&<div role="status" className="toast"><Check size={18}/>{toast}<button aria-label="Cerrar aviso" onClick={()=>setToast("")}><X size={16}/></button></div>}
  </div>;
}
function Login({onLogin,connectionError}:{onLogin:()=>Promise<void>;connectionError:ApiError|null}){
  const [email,setEmail]=useState("tienda@vidracred.local"),[password,setPassword]=useState(""),[error,setError]=useState<ApiError|null>(null),[busy,setBusy]=useState(false);
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError(null);try{await api("auth/login",{email,password});await onLogin();}catch(e){setError(e as ApiError);}finally{setBusy(false);}}
  return <div className="login"><section className="login-story"><a className="brand" href="/"><div className="brand-icon"><GlassWater/></div><span>Vidra<span className="brand-light">Cred</span></span></a><div><span className="eyebrow">CRÉDITO COMERCIAL, CON CLARIDAD</span><h1>Cada crédito.<br/>Cada cuota.<br/><span>Todo en orden.</span></h1><p>Una cuenta corriente para acompañar el crecimiento de su negocio.</p><div className="login-sample"><div><span>Próximo vencimiento</span><strong>05 oct 2026</strong></div><Badge status="POR_VENCER"/><hr/><div><span>Cuota · Paquete Cosmética</span><strong>S/ 735.34</strong></div><small><ShieldCheck size={14}/>Condiciones claras desde el primer día</small></div></div><small>VIDRA PLASTIC · LIMA, PERÚ</small></section><section className="login-form"><div><span className="eyebrow">BIENVENIDO A VIDRACRED</span><h2>Ingrese a su espacio</h2><p>Administre su tienda o consulte el estado de su crédito.</p><form onSubmit={submit}><Notice error={error??connectionError}/><Field label="Correo electrónico"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username"/></Field><Field label="Contraseña"><input type="password" required value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" placeholder="Ingrese su contraseña" maxLength={128}/></Field><button className="primary full" disabled={busy}>{busy?"Ingresando…":"Iniciar sesión"}<ArrowUpRight size={17}/></button></form><div className="demo-accounts"><strong>Accesos de ejemplo</strong><p>Elija el tipo de acceso para completar el correo y luego escriba su contraseña.</p><div>{[["Tienda","tienda"],["Sistema","sistema"],["Cliente","cliente"]].map(([label,value])=><button type="button" key={value} onClick={()=>setEmail(value+"@vidracred.local")} className={email.startsWith(value+"@")?"chosen":""}>{label}</button>)}</div></div><small className="login-note"><ShieldCheck size={14}/>Acceso local con permisos por tienda y por cliente</small></div></section></div>;
}
function PageTitle({eyebrow,title,subtitle,children}:{eyebrow:string;title:string;subtitle:string;children?:ReactNode}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{children}</div>;}
function Dashboard({data,asOf,go}:{data:Data;asOf:string;go:(v:View,id?:string)=>void}){
  const currencyTotals=(currency:Currency)=>{const s=data.credits.filter(c=>c.currency===currency).map(c=>statement(c,asOf));return {outstanding:sum(s.map(s=>s.outstanding)),paid:sum(s.map(s=>s.paid)),overdue:sum(s.map(s=>s.overdue)),late:sum(s.map(s=>s.paidLateFee))};};
  const pen=currencyTotals("PEN"),usd=currencyTotals("USD"),active=data.credits.filter(c=>statement(c,asOf).outstanding!=="0.00");
  const due=data.credits.flatMap(c=>statement(c,asOf).rows.filter(r=>r.pending!=="0.00").map(r=>({...r,credit:c}))).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
  return <><PageTitle eyebrow="SU NEGOCIO, AL DÍA" title="Una mirada a su cartera" subtitle={`Estado financiero de ${data.stores.find(s=>s.id===data.storeId)?.name} al ${date(asOf)}.`}><button className="primary" onClick={()=>go("compra")}><Plus size={17}/>Nueva compra</button></PageTitle><div className="metrics"><Metric label="Saldo financiero pendiente" value={fmt(pen.outstanding)} note={`${active.filter(c=>c.currency==="PEN").length} créditos con saldo en soles`} accent/><Metric label="Pagos recibidos" value={fmt(pen.paid)} note="Mora, interés y amortización cobrados"/><Metric label="Deuda vencida" value={fmt(pen.overdue)} note="Cuotas impagas vencidas más su mora"/><Metric label="Clientes de la tienda" value={String(data.clients.filter(c=>c.active).length).padStart(2,"0")} note={(n=>`${n} ${n===1?"paquete disponible":"paquetes disponibles"}`)(data.packages.filter(p=>p.active).length)}/></div><div className="currency-strip"><span>Moneda extranjera</span><strong>Saldo {fmt(usd.outstanding,"USD")}</strong><span>Cobros {fmt(usd.paid,"USD")}</span><span>Vencido {fmt(usd.overdue,"USD")}</span><small>Los totales se presentan por moneda.</small></div>
    <div className="dashboard-grid"><section className="card"><div className="card-head"><div><h2>Próximos cobros</h2><p>Vencimientos y atrasos pendientes</p></div><button className="text-button" onClick={()=>go("corte")}>Ver listado<ArrowUpRight size={15}/></button></div><div className="table-wrap"><table><thead><tr><th>Cliente / crédito</th><th>Vencimiento</th><th>Estado</th><th className="num">Por cobrar</th><th/></tr></thead><tbody>{due.slice(0,6).map(r=><tr key={r.credit.id+r.number}><td><strong className="truncate">{r.credit.clientName}</strong><small>{shortId(r.credit.id)} · cuota {r.number}</small></td><td className="mono">{date(r.dueDate)}</td><td><Badge status={r.status}/></td><td className="num">{fmt(r.pending,r.credit.currency)}</td><td><button aria-label={"Ver crédito de "+r.credit.clientName} className="icon-button" onClick={()=>go("cronograma",r.credit.id)}><ChevronRight size={17}/></button></td></tr>)}</tbody></table>{!due.length&&<Empty>No hay cobros pendientes a esta fecha.</Empty>}</div></section><section className="card portfolio"><div className="card-head"><div><h2>Líneas de crédito</h2><p>Saldo financiero / línea asignada</p></div><Wallet size={18}/></div>{data.clients.filter(c=>c.currency==="PEN").slice(0,5).map(c=>{const line=creditLine(c.credit_limit,data.credits.filter(x=>x.clientId===c.id),asOf);return <div className="line-item" key={c.id}><div><strong>{c.name}</strong><span>{fmt(line.outstanding)}</span></div><div className="progress"><span style={{width:Math.min(100,new D(line.outstanding).div(line.limit).mul(100).toNumber())+"%"}}/></div><small>Disponible {fmt(line.available)}<span>de {fmt(line.limit)}</span></small></div>;})}<button className="secondary full" onClick={()=>go("clientes")}>Administrar clientes<ArrowUpRight size={15}/></button></section></div><section className="card activity"><div className="card-head"><div><h2>Actividad registrada</h2><p>Últimas operaciones de la tienda</p></div><ShieldCheck size={18}/></div>{data.audit.length===0&&<p className="activity-empty">Aún no hay operaciones registradas.</p>}{data.audit.slice(0,4).map((a,i)=><div className="activity-row" key={i}><div className="activity-icon"><Check size={15}/></div><div><strong>{actionLabels[a.action]??a.action.replaceAll("_"," ").toLowerCase()}</strong><small>{a.user_name??"Sistema"}</small></div><time>{new Date(a.created_at).toLocaleString("es-PE",{timeZone:"America/Lima",dateStyle:"short",timeStyle:"short"})}</time></div>)}</section></>;
}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){return <div className="modal-backdrop" onClick={onClose}><section role="dialog" aria-modal="true" aria-label={title} className="modal" onClick={e=>e.stopPropagation()}><div className="card-head"><h2>{title}</h2><button className="icon-button" aria-label="Cerrar" onClick={onClose}><X size={19}/></button></div>{children}</section></div>;}
function EntityForm({children,onSave,onClose}:{children:(err:ApiError|null)=>ReactNode;onSave:(v:FormData)=>Promise<void>;onClose:()=>void}){
  const [err,setErr]=useState<ApiError|null>(null),[busy,setBusy]=useState(false);
  return <form className="entity-form" onSubmit={async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);setBusy(true);setErr(null);try{await onSave(fd);onClose();}catch(e){setErr(e as ApiError);}finally{setBusy(false);}}}><Notice error={err}/>{children(err)}<div className="form-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy}>{busy?"Guardando…":"Guardar cambios"}<Check size={16}/></button></div></form>;
}
const textValue=(f:FormData,k:string)=>String(f.get(k)??"");
function Clients({data,asOf,refresh,notify,go}:{data:Data;asOf:string;refresh:()=>Promise<unknown>;notify:(s:string)=>void;go:(v:View,id?:string)=>void}){
  const [search,setSearch]=useState(""),[edit,setEdit]=useState<ClientRow|"new"|null>(null);
  const client=edit&&edit!=="new"?edit:null;
  return <><PageTitle eyebrow="CARTERA DE CLIENTES" title="Condiciones que quedan claras" subtitle="Defina la línea, la tasa y el plazo de cada cliente."><button className="primary" onClick={()=>setEdit("new")}><Plus size={17}/>Nuevo cliente</button></PageTitle><section className="card"><div className="card-head"><h2>{data.clients.length} clientes registrados</h2><label className="search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar nombre o documento" aria-label="Buscar cliente"/></label></div><div className="table-wrap"><table><thead><tr><th>Cliente</th><th>TEA vigente</th><th className="num">Línea asignada</th><th className="num">Saldo pendiente</th><th className="num">Disponible</th><th>Plazo</th><th/></tr></thead><tbody>{data.clients.filter(c=>(c.name+" "+c.document).toLowerCase().includes(search.toLowerCase())).map(c=>{const line=creditLine(c.credit_limit,data.credits.filter(x=>x.clientId===c.id),asOf);return <tr key={c.id}><td><strong>{c.name}</strong><small>{c.document} · {c.currency}{!c.active?" · Inactivo":""}</small></td><td className="mono">{rate(c.tea)}</td><td className="num">{fmt(c.credit_limit,c.currency)}</td><td className="num">{fmt(line.outstanding,c.currency)}</td><td className="num positive">{fmt(line.available,c.currency)}</td><td>{c.max_months} meses</td><td><button className="text-button" onClick={()=>setEdit(c)}>Editar<ChevronRight size={14}/></button></td></tr>;})}</tbody></table></div></section><div className="info-note"><ShieldCheck size={18}/><p>Los cambios de tasa, plazo o línea se aplican a las siguientes compras. Cada crédito conserva las condiciones con las que se registró.</p></div>{edit&&<Modal title={client?"Editar cliente y condiciones":"Registrar cliente"} onClose={()=>setEdit(null)}><EntityForm onClose={()=>setEdit(null)} onSave={async f=>{const payload={...(client?{id:client.id}:{}),storeId:data.storeId,name:textValue(f,"name"),document:textValue(f,"document"),phone:textValue(f,"phone"),address:textValue(f,"address"),currency:textValue(f,"currency"),tea:new D(textValue(f,"tea")).div(100).toFixed(12),creditLimit:textValue(f,"creditLimit"),maxMonths:Number(f.get("maxMonths")),active:f.get("active")==="on",...(f.get("portalEmail")?{portalEmail:textValue(f,"portalEmail"),portalPassword:textValue(f,"portalPassword")}: {})};await api("clients",payload);await refresh();notify("Cliente y condiciones guardados.");}}>{err=><><div className="form-grid"><Field label="Nombre o razón social" name="name" error={err}><input required name="name" maxLength={150} defaultValue={client?.name}/></Field><Field label="DNI o RUC" hint="8 u 11 dígitos" name="document" error={err}><input required name="document" pattern="([0-9]{8}|[0-9]{11})" defaultValue={client?.document}/></Field><Field label="Teléfono"><input name="phone" maxLength={20} defaultValue={client?.phone}/></Field><Field label="Dirección"><input name="address" maxLength={200} defaultValue={client?.address}/></Field><Field label="Moneda" hint="Una sola moneda por cliente" name="currency" error={err}><select name="currency" defaultValue={client?.currency??"PEN"}><option>PEN</option><option>USD</option></select></Field><Field label="TEA pactada (%)" hint="Entre 15 % y 25 %" name="tea" error={err}><input required type="number" name="tea" min={15} max={25} step="0.0000001" defaultValue={client?new D(client.tea).mul(100).toString():"20"}/></Field><p className="formula-hint">La TEA se convierte a tasa quincenal: <code>TEQ = (1 + TEA)^(15/360) − 1</code>. Con 20 % la TEQ es {rate(teq("0.20"))}. La mora usa TEA moratoria {rate(POLICY.mora)} (TED {rate(ted(POLICY.mora))} por día).</p><Field label="Línea de crédito" hint="Entre 1 000 y 1 000 000" name="creditLimit" error={err}><input required name="creditLimit" type="number" min={1000} max={1000000} step="0.01" defaultValue={client?.credit_limit??"5000"}/></Field><Field label="Plazo máximo" hint="1 a 5 meses" name="maxMonths" error={err}><select name="maxMonths" defaultValue={client?.max_months??5}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} meses</option>)}</select></Field></div><label className="checkbox"><input name="active" type="checkbox" defaultChecked={client?.active??true}/>Cliente activo</label><details><summary>Acceso al portal del cliente</summary><p>Complete ambos campos para crear o renovar el acceso de este cliente.</p><div className="form-grid"><Field label="Correo del portal"><input name="portalEmail" type="email"/></Field><Field label="Contraseña del portal" hint="Al menos 10 caracteres"><input name="portalPassword" type="password" minLength={10} maxLength={128} autoComplete="new-password"/></Field></div></details></>}</EntityForm></Modal>}</>;
}
function Packages({data,refresh,notify}:{data:Data;refresh:()=>Promise<unknown>;notify:(s:string)=>void}){
  const [edit,setEdit]=useState<PackageRow|"new"|null>(null),p=edit&&edit!=="new"?edit:null;
  return <><PageTitle eyebrow="CATÁLOGO DE LA TIENDA" title="Un paquete para cada compra" subtitle="Montos fijos entre 1 000 y 5 000, en múltiplos de 100."><button className="primary" onClick={()=>setEdit("new")}><Plus size={17}/>Nuevo paquete</button></PageTitle><div className="package-grid">{data.packages.map((p,i)=><article className={"card package-card "+(!p.active?"inactive":"")} key={p.id}><div className={"package-art art-"+i%3}><GlassWater size={52} strokeWidth={1}/><GlassWater size={70} strokeWidth={1}/><GlassWater size={42} strokeWidth={1}/><span>{p.currency}</span></div><div className="package-body"><span className="eyebrow">{p.active?"DISPONIBLE":"INACTIVO"}</span><h2>{p.name}</h2><p>{p.detail}</p><div><strong>{fmt(p.amount,p.currency)}</strong><button className="text-button" onClick={()=>setEdit(p)}>Editar<ChevronRight size={15}/></button></div></div></article>)}</div>{edit&&<Modal title={p?"Editar paquete":"Crear paquete"} onClose={()=>setEdit(null)}><EntityForm onClose={()=>setEdit(null)} onSave={async f=>{await api("packages",{...(p?{id:p.id}:{}),storeId:data.storeId,name:textValue(f,"name"),detail:textValue(f,"detail"),currency:textValue(f,"currency"),amount:textValue(f,"amount"),active:f.get("active")==="on"});await refresh();notify("Paquete guardado.");}}>{err=><><Field label="Nombre del paquete" name="name" error={err}><input name="name" required maxLength={120} defaultValue={p?.name}/></Field><Field label="Contenido del paquete"><textarea name="detail" maxLength={500} defaultValue={p?.detail} rows={3}/></Field><div className="form-grid"><Field label="Precio fijo" hint="1 000 a 5 000, múltiplo de 100" name="amount" error={err}><input required name="amount" type="number" min={1000} max={5000} step={100} defaultValue={p?.amount??"1000"}/></Field><Field label="Moneda"><select name="currency" defaultValue={p?.currency??"PEN"}><option>PEN</option><option>USD</option></select></Field></div><label className="checkbox"><input name="active" type="checkbox" defaultChecked={p?.active??true}/>Paquete activo</label></>}</EntityForm></Modal>}</>;
}
function Purchase({data,store,onDone}:{data:Data;store:StoreRow;onDone:(id:string)=>Promise<void>}){
  const [clientId,setClientId]=useState(data.clients.find(c=>c.active)?.id??""),[packageId,setPackageId]=useState(()=>{const c0=data.clients.find(c=>c.active);return (data.packages.find(p=>p.active&&p.currency===c0?.currency)??data.packages.find(p=>p.active))?.id??"";}),[purchaseDate,setPurchaseDate]=useState(today()),[months,setMonths]=useState(1),[grace,setGrace]=useState("SS"),[quote,setQuote]=useState<Quote|null>(null),[error,setError]=useState<ApiError|null>(null),[busy,setBusy]=useState(false),[key,setKey]=useState("");
  const client=data.clients.find(c=>c.id===clientId),payload={storeId:data.storeId,clientId,packageId,purchaseDate,months,grace};
  function change(fn:()=>void){fn();setQuote(null);setError(null);}
  const line=client?creditLine(client.credit_limit,data.credits.filter(c=>c.clientId===clientId),purchaseDate||today()):null;
  return <><PageTitle eyebrow="NUEVA OPERACIÓN" title="Registre una compra al crédito" subtitle="Revise el cálculo y el cronograma antes de confirmar la operación."/><div className="purchase-layout"><section className="card"><div className="card-head"><div><h2><span className="step">1</span>Condiciones de la compra</h2><p>Las tasas y el calendario se toman de la tienda y del cliente.</p></div></div><form className="purchase-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError(null);try{setQuote(await api<Quote>("simulate",payload));setKey(crypto.randomUUID());}catch(e){setQuote(null);setError(e as ApiError);}finally{setBusy(false);}}}><Notice error={error?.field?null:error}/><Field label="Cliente" hint="Debe contar con una línea activa" name="clientId" error={error}><select required value={clientId} onChange={e=>change(()=>{setClientId(e.target.value);const c=data.clients.find(c=>c.id===e.target.value);const p=data.packages.find(p=>p.active&&p.currency===c?.currency);if(p)setPackageId(p.id);})}>{data.clients.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name} · {c.currency}</option>)}</select></Field>{line&&<div className="client-summary"><span>Línea {fmt(line.limit,client!.currency)}</span><strong>Disponible {fmt(line.available,client!.currency)}</strong></div>}<Field label="Paquete" hint="La moneda debe coincidir con la del cliente" name="packageId" error={error}><select required value={packageId} onChange={e=>change(()=>setPackageId(e.target.value))}>{data.packages.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name} · {fmt(p.amount,p.currency)}</option>)}</select></Field><div className="form-grid"><Field label="Fecha de compra" hint="No puede ser posterior a hoy" name="purchaseDate" error={error}><input type="date" required value={purchaseDate} max={today()} min="1900-01-01" onChange={e=>change(()=>setPurchaseDate(e.target.value))}/></Field><Field label="Plazo en meses" hint={`Máximo del cliente: ${client?.max_months??5} meses`} name="months" error={error}><select value={months} onChange={e=>change(()=>{setMonths(Number(e.target.value));setGrace("S".repeat(Number(e.target.value)*2));})}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} {n===1?"mes":"meses"} · {n*2} cuotas</option>)}</select></Field></div><Field label="Gracia de cada quincena" hint={`Escriba ${months*2} letras. T = total, P = parcial, S = sin gracia. Ejemplo: ${months===1?"TS":"TP"+"S".repeat(months*2-2)}`} name="grace" error={error}><input className="mono grace-input" value={grace} maxLength={10} onChange={e=>change(()=>setGrace(e.target.value.toUpperCase()))} required/><div className="grace-preview">{Array.from({length:months*2},(_,i)=><span key={i} className={"grace-"+grace[i]}>{i+1}<b>{grace[i]??"?"}</b></span>)}</div></Field><button className="primary full" disabled={busy||!clientId||!packageId}><Eye size={17}/>{busy?"Calculando…":"Generar vista previa"}</button></form></section><aside className="purchase-aside"><section className="card conditions"><span className="eyebrow">CONDICIONES APLICABLES</span><h2>El cálculo, a la vista</h2><dl><div><dt>TEQ del cliente</dt><dd>{client?rate(teq(client.tea)):"—"}</dd></div><div><dt>TED moratoria</dt><dd>{rate(ted(POLICY.mora))}</dd></div><div><dt>TEA del cliente</dt><dd>{client?rate(client.tea):"—"}</dd></div><div><dt>TEA moratoria</dt><dd>{rate(POLICY.mora)}</dd></div><div><dt>Día de corte</dt><dd>{store.cut_day} de cada mes</dd></div><div><dt>Vencimientos</dt><dd>{[store.pay_day,((store.pay_day+14)%30)+1].sort((a,b)=>a-b).join(" y ")}</dd></div><div><dt>Base financiera</dt><dd>360 días</dd></div></dl><p className="formula-hint"><code>TEQ = (1 + TEA)^(15/360) − 1</code><br/><code>TED = (1 + TEA moratoria)^(1/360) − 1</code><br/>La gracia inicial y el atraso usan los días reales entre fechas.</p></section><div className="info-note"><HelpCircle size={19}/><p>La gracia total capitaliza el interés. La parcial cobra solo interés. Debe quedar al menos una cuota sin gracia.</p></div></aside></div>{quote&&<section className="card preview"><div className="card-head"><div><h2><span className="step">2</span>Vista previa del crédito</h2><p>{quote.clientName} · {quote.packageName}</p></div><span className="badge por_vencer">Simulación sin registrar</span></div><div className="metrics preview-metrics"><Metric label="Saldo inicial · fila 0" value={fmt(quote.schedule.initialBalance,quote.schedule.input.currency)} note={`${quote.schedule.initialDays} días de gracia inicial`}/><Metric label="Cuota ordinaria" value={fmt(quote.schedule.ordinaryPayment,quote.schedule.input.currency)} note="La última cuota ajusta los céntimos"/><Metric label="Interés compensatorio total" value={fmt(quote.schedule.totals.interest,quote.schedule.input.currency)} note={`Desfase inicial ${fmt(quote.schedule.initialInterest,quote.schedule.input.currency)} + interés de las filas ${fmt(sum(quote.schedule.rows.map(r=>r.interest)),quote.schedule.input.currency)}`}/></div><ScheduleTable schedule={quote.schedule} currency={quote.schedule.input.currency}/><LegalNote quote={quote}/><div className="confirm-bar"><p><ShieldCheck size={17}/>El servidor volverá a validar las condiciones y la línea disponible.</p><button className="primary" disabled={busy} onClick={async()=>{setBusy(true);setError(null);try{const r=await api<{id:string}>("credits",{...payload,idempotencyKey:key,previewFingerprint:quote.fingerprint});await onDone(r.id);}catch(e){setError(e as ApiError);}finally{setBusy(false);}}}><Check size={17}/>{busy?"Registrando…":"Confirmar y registrar crédito"}</button></div><Notice error={error?.field?null:error}/></section>}</>;
}
function LegalNote({quote}:{quote:Quote}){const l=quote.legal;return <details className="legal-note"><summary>Referencias y política académica</summary>{l?<p>Vigencia de referencia {date(l.from)} a {date(l.to)} · máximo compensatorio {rate(l.compensatory)} · máximo moratorio {rate(l.moratory)}. <a href={l.source} target="_blank" rel="noreferrer">BCRP</a>. La mora del modelo es {rate(POLICY.mora)} TEA sobre la cuota vencida, según la política fijada para el curso; {new D(l.moratory).lt(POLICY.mora)?"supera el máximo moratorio de referencia para esta moneda y vigencia, que se muestra solo como información.":"se presenta separada del límite regulatorio."}</p>:<p>No hay una referencia verificada para esta fecha. El cálculo utiliza las condiciones académicas de VidraCred.</p>}</details>;}
type StatementRow=ReturnType<typeof statement>["rows"][number];
function ScheduleTable({schedule,rows,currency}:{schedule:Schedule;rows?:StatementRow[];currency:Currency}){
  return <div className="table-wrap schedule-wrap"><table className="schedule-table"><caption>Cronograma pactado y pagos recibidos · importes en {currency==="PEN"?"soles (S/)":"dólares (US$)"}</caption><thead><tr><th>N.º</th><th>Vencimiento</th><th>PG</th><th className="num">Saldo inicial</th><th className="num">Interés</th><th className="num">Cuota</th><th className="num">Amortización</th><th className="num">Saldo final</th>{rows&&<><th>Pago real</th><th className="num">Días atraso</th><th className="num">Mora</th><th className="num">Total pagado</th><th>Estado</th></>}</tr></thead><tbody><tr className="row-zero"><td>0</td><td className="mono">{date(schedule.baseDate)}</td><td>—</td><td className="num">—</td><td className="num">—</td><td className="num">—</td><td className="num">—</td><td className="num">{num(schedule.initialBalance)}</td>{rows&&<><td>—</td><td>—</td><td>—</td><td>—</td><td><span className="row-label">Fila inicial</span></td></>}</tr>{(rows??schedule.rows).map((r,i)=><tr key={r.number} className={r.grace==="T"?"row-grace":""}><td>{r.number}</td><td className="mono">{date(r.dueDate)}</td><td><span title={r.grace==="T"?"Gracia total":r.grace==="P"?"Gracia parcial":"Sin gracia"} className={"grace-tag "+r.grace}>{r.grace}</span></td><td className="num">{num(r.opening)}</td><td className="num">{num(r.interest)}</td><td className="num strong">{num(r.payment)}</td><td className="num">{num(r.principal)}</td><td className="num">{num(r.closing)}</td>{rows&&<><td className="mono">{date(rows[i].paidDate)}</td><td className="num">{rows[i].daysLate}</td><td className="num">{num(rows[i].lateFee)}</td><td className="num">{num(rows[i].totalPaid)}</td><td><Badge status={rows[i].status}/></td></>}</tr>)}</tbody><tfoot><tr><td colSpan={4}>TOTALES · el interés no incluye el desfase de la fila 0</td><td className="num">{num(sum(schedule.rows.map(r=>r.interest)))}</td><td className="num">{num(schedule.totals.payments)}</td><td className="num">{num(schedule.totals.principal)}</td><td className="num">{num("0")}</td>{rows&&<><td>RECIBIDO</td><td/><td className="num">{num(sum(rows.filter(r=>r.paidDate).map(r=>r.lateFee)))}</td><td className="num">{num(sum(rows.map(r=>r.totalPaid)))}</td><td/></>}</tr></tfoot></table></div>;
}
function Schedules({data,asOf,selected,setSelected,go}:{data:Data;asOf:string;selected:string;setSelected:(s:string)=>void;go:(v:View,id?:string)=>void}){
  const c=data.credits.find(c=>c.id===selected)??data.credits.find(c=>c.id.endsWith("000002"))??data.credits[0];
  if(!c)return <><PageTitle eyebrow="CRONOGRAMAS" title="Sus créditos, cuota por cuota" subtitle="Los cronogramas aparecerán al registrar la primera compra."/><Empty>Aún no hay créditos registrados.</Empty><button className="primary" onClick={()=>go("compra")}>Nueva compra</button></>;
  const s=statement(c,asOf),sc=c.schedule;
  return <><PageTitle eyebrow="CRONOGRAMA Y ESTADO DE CUENTA" title={shortId(c.id)+" · "+c.packageName} subtitle={c.clientName}><div className="actions"><button className="secondary" onClick={()=>csvDownload(shortId(c.id)+".csv",["N","Vencimiento","PG","Saldo inicial","Interés","Cuota","Amortización","Saldo final","Pago real","Días atraso","Mora","Total pagado","Estado"],[[0,sc.baseDate,"—","","","","",sc.initialBalance,"","","","","FILA 0"],...s.rows.map(r=>[r.number,r.dueDate,r.grace,r.opening,r.interest,r.payment,r.principal,r.closing,r.paidDate??"",r.daysLate,r.lateFee,r.totalPaid,labels[r.status]])])}><Download size={16}/>CSV</button><button className="primary" onClick={()=>go("pagos",c.id)}><ReceiptText size={17}/>Registrar pago</button></div></PageTitle><div className="select-bar"><Field label="Crédito"><select value={c.id} onChange={e=>setSelected(e.target.value)}>{data.credits.map(x=><option key={x.id} value={x.id}>{shortId(x.id)} · {x.clientName} · {x.packageName}</option>)}</select></Field><div><span>Compra {date(sc.input.purchaseDate)}</span><span>{sc.input.months} meses · {sc.rows.length} quincenas</span><span>TEQ {rate(sc.teq)}</span></div></div><div className="metrics"><Metric label="Saldo financiero pendiente" value={fmt(s.outstanding,c.currency)} note="Capital e interés capitalizado, menos amortizaciones pagadas" accent/><Metric label="Pagos recibidos" value={fmt(s.paid,c.currency)} note={`Mora cobrada ${fmt(s.paidLateFee,c.currency)}`}/><Metric label="Próximo vencimiento" value={date(s.nextDue)} note={`Deuda vencida ${fmt(s.overdue,c.currency)}`}/><Metric label="Interés compensatorio total" value={fmt(sc.totals.interest,c.currency)} note={`Desfase inicial ${fmt(sc.initialInterest,c.currency)} + interés de las filas ${fmt(sum(sc.rows.map(r=>r.interest)),c.currency)}`}/></div><section className="card"><div className="card-head"><div><h2>Detalle quincenal</h2><p>La tabla conserva el pacto original. El estado y los cobros corresponden al {date(asOf)}.</p></div><span className="pill">{c.currency} · Base 360</span></div><ScheduleTable schedule={sc} rows={s.rows} currency={c.currency}/></section><div className="reconciliation"><section className="card"><h2>Conciliación del interés</h2><dl><div><dt>Desfase inicial · {sc.initialDays} días</dt><dd>{fmt(sc.initialInterest,c.currency)}</dd></div><div><dt>Interés de gracia total</dt><dd>{fmt(sum(sc.rows.map(r=>r.capitalized)),c.currency)}</dd></div><div><dt>Interés en cuotas por cobrar</dt><dd>{fmt(sc.totals.cashInterest,c.currency)}</dd></div><div className="total"><dt>Total compensatorio proyectado</dt><dd>{fmt(sc.totals.interest,c.currency)}</dd></div></dl></section><section className="card"><h2>A la fecha de consulta</h2><dl><div><dt>Interés ya capitalizado</dt><dd>{fmt(s.capitalized,c.currency)}</dd></div><div><dt>Interés cobrado en cuotas</dt><dd>{fmt(s.paidInterest,c.currency)}</dd></div><div><dt>Amortizaciones recibidas</dt><dd>{fmt(s.paidPrincipal,c.currency)}</dd></div><div><dt>Mora pendiente</dt><dd>{fmt(s.pendingLateFee,c.currency)}</dd></div></dl></section></div><div className="info-note"><HelpCircle size={18}/><p>La fila 0 incorpora el desfase inicial de {sc.initialDays} días. Las cuotas futuras del cronograma no reducen el saldo de la cuenta. Las filas T tienen estado de gracia y no se cobran.</p></div></>;
}
function PaymentView({data,selected,setSelected,onDone}:{data:Data;selected:string;setSelected:(s:string)=>void;onDone:(date:string)=>Promise<void>}){
  const [paidDate,setPaidDate]=useState(today()),[reference,setReference]=useState(""),[error,setError]=useState<ApiError|null>(null),[busy,setBusy]=useState(false),[key,setKey]=useState("");
  useEffect(()=>setKey(crypto.randomUUID()),[]);
  const nextDue=(c:Credit)=>c.schedule.rows.find(r=>r.grace!=="T"&&!c.payments.some(p=>p.installmentNumber===r.number))?.dueDate??"9999-12-31";
  const candidates=data.credits.filter(c=>c.schedule.rows.some(r=>r.grace!=="T"&&!c.payments.some(p=>p.installmentNumber===r.number))).sort((a,b)=>nextDue(a).localeCompare(nextDue(b)));
  const c=candidates.find(c=>c.id===selected)??candidates[0],r=c?.schedule.rows.find(r=>r.grace!=="T"&&!c.payments.some(p=>p.installmentNumber===r.number));
  const fee=r&&paidDate?lateFee(r.payment,r.dueDate,paidDate):{days:0,amount:"0.00"},total=r?sum([r.payment,fee.amount]):"0.00";
  return <><PageTitle eyebrow="COBRANZA" title="Registre un pago completo" subtitle="La imputación se realiza en este orden: mora, interés y amortización."/>{!c||!r?<Empty>No hay cuotas pendientes de pago.</Empty>:<div className="payment-layout"><section className="card"><div className="card-head"><h2>Datos del cobro</h2><ReceiptText size={19}/></div><form className="purchase-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError(null);try{await api("payments",{creditId:c.id,installmentNumber:r.number,paidDate,total,reference,idempotencyKey:key});setKey(crypto.randomUUID());setReference("");await onDone(paidDate);}catch(e){setError(e as ApiError);}finally{setBusy(false);}}}><Notice error={error}/><Field label="Crédito pendiente"><select value={c.id} onChange={e=>{setSelected(e.target.value);setError(null);setKey(crypto.randomUUID());}}>{candidates.map(x=><option key={x.id} value={x.id}>{shortId(x.id)} · {x.clientName}</option>)}</select></Field><div className="payment-credit"><span>CUOTA {r.number} DE {c.schedule.rows.length}</span><h3>{c.packageName}</h3><p>Vencimiento pactado <strong>{date(r.dueDate)}</strong></p></div><div className="form-grid"><Field label="Fecha de pago real" hint={today()<r.dueDate?`Aún no vence: se podrá registrar desde el ${date(r.dueDate)}`:"Desde el vencimiento hasta hoy"} name="paidDate" error={error}><input required type="date" value={paidDate} min={r.dueDate} max={today()} onChange={e=>setPaidDate(e.target.value)}/></Field><Field label="Días de atraso"><input readOnly value={fee.days}/></Field></div><Field label="Referencia del comprobante" hint="Número de operación, recibo o constancia" name="reference" error={error}><input required maxLength={120} value={reference} onChange={e=>setReference(e.target.value)} placeholder="Ej. REC-2026-001"/></Field><Field label="Importe recibido" hint="El flujo admite solo el pago completo de la cuota y su mora" name="total" error={error}><input className="amount-input" value={fmt(total,c.currency)} readOnly/></Field><button className="primary full" disabled={busy||!paidDate||paidDate<r.dueDate}><Check size={17}/>{busy?"Registrando…":"Confirmar y registrar pago"}</button></form></section><aside><section className="card allocation"><span className="eyebrow">DISTRIBUCIÓN DEL PAGO</span><h2>Así se aplica el cobro</h2>{[["01","Mora",fee.amount],["02","Interés compensatorio",r.interest],["03","Amortización de capital",r.principal]].map(([n,label,value])=><div className="allocation-row" key={n}><span>{n}</span><div><strong>{label}</strong><small>{n==="01"?`${fee.days} días · TEA ${rate(c.schedule.input.mora??POLICY.mora)}`:n==="02"?"Interés de la cuota pactada":"Importe que libera línea de crédito"}</small></div><b>{fmt(value,c.currency)}</b></div>)}<div className="allocation-total"><span>Total a recibir</span><strong>{fmt(total,c.currency)}</strong></div></section><div className="info-note"><ShieldCheck size={18}/><p>La cuota más antigua se paga primero. Cada pago genera un registro independiente y queda protegido frente a duplicados.</p></div></aside></div>}</>;
}
function CutView({data,asOf,store,go}:{data:Data;asOf:string;store:StoreRow;go:(v:View,id?:string)=>void}){
  const base=new Date(asOf+"T00:00:00Z");let m=base.getUTCMonth();if(asOf<monthDate(base.getUTCFullYear(),m,store.cut_day))m--;
  const [month,setMonth]=useState(monthDate(base.getUTCFullYear(),m,1).slice(0,7));
  const cut=monthDate(Number(month.slice(0,4)),Number(month.slice(5,7))-1,store.cut_day),listing=cutListing(data.credits,cut,store.cut_day,asOf);
  return <><PageTitle eyebrow="PLANIFICACIÓN DE COBRANZA" title="El ciclo completo de sus cobros" subtitle="Incluye las cuotas del ciclo seleccionado y los atrasos pendientes a la fecha de consulta."><button className="secondary" onClick={()=>csvDownload("corte-"+cut+".csv",["Cliente","Crédito","Cuota","Vencimiento","Moneda","Cuota pactada","Mora","Por cobrar","Grupo"],listing.rows.map(r=>[r.clientName,shortId(r.creditId),r.number,r.dueDate,r.currency,r.payment,r.lateFee,r.pending,r.category]))}><Download size={16}/>Exportar CSV</button></PageTitle><div className="select-bar"><Field label="Mes de corte"><input type="month" min="1900-01" max="2199-12" required value={month} onChange={e=>{if(e.target.value)setMonth(e.target.value);}}/></Field><div><strong>Corte {date(listing.start)}</strong><span>Ciclo: después del {date(listing.start)} hasta el {date(listing.end)}</span></div></div><div className="metrics two"><Metric label="Por cobrar · PEN" value={fmt(sum(listing.rows.filter(r=>r.currency==="PEN").map(r=>r.pending)))} note="Cuotas del ciclo más atrasos anteriores" accent/><Metric label="Por cobrar · USD" value={fmt(sum(listing.rows.filter(r=>r.currency==="USD").map(r=>r.pending)),"USD")} note="Sin conversión ni mezcla de monedas"/></div><section className="card"><div className="card-head"><div><h2>{listing.rows.length} cuotas pendientes</h2><p>Las cuotas de gracia total y los pagos ya recibidos están excluidos.</p></div><span className="pill">Consulta {date(asOf)}</span></div><div className="table-wrap"><table><thead><tr><th>Cliente / paquete</th><th>Cuota</th><th>Vencimiento</th><th>Grupo</th><th>Estado al consultar</th><th className="num">Cuota</th><th className="num">Mora</th><th className="num">Por cobrar</th><th/></tr></thead><tbody>{listing.rows.map(r=><tr key={r.creditId+r.number}><td><strong>{r.clientName}</strong><small>{r.packageName}</small></td><td>{r.number}</td><td className="mono">{date(r.dueDate)}</td><td>{r.category==="CICLO"?"Del ciclo":"Atraso anterior"}</td><td><Badge status={r.status}/></td><td className="num">{fmt(r.payment,r.currency)}</td><td className="num">{fmt(r.lateFee,r.currency)}</td><td className="num strong">{fmt(r.pending,r.currency)}</td><td><button className="text-button" onClick={()=>go("cronograma",r.creditId)}>Ver<ChevronRight size={14}/></button></td></tr>)}</tbody></table>{!listing.rows.length&&<Empty>No hay cuotas por cobrar para este ciclo y fecha de consulta.</Empty>}</div></section></>;
}
function Portal({data,asOf}:{data:Data;asOf:string}){
  const [clientId,setClientId]=useState(data.clients[0]?.id??"");const client=data.clients.find(c=>c.id===clientId)??data.clients[0];
  if(!client)return <Empty>No hay un cliente disponible para consultar.</Empty>;
  const credits=data.credits.filter(c=>c.clientId===client.id&&c.schedule.input.purchaseDate<=asOf),line=creditLine(client.credit_limit,credits,asOf),stats=credits.map(c=>statement(c,asOf));
  return <><PageTitle eyebrow="PORTAL DEL CLIENTE" title={data.actor.role==="CLIENTE"?"Su crédito, con toda claridad":"Consulta de la cuenta del cliente"} subtitle={client.name}/>{data.actor.role!=="CLIENTE"&&<div className="select-bar"><Field label="Cliente a consultar"><select value={client.id} onChange={e=>setClientId(e.target.value)}>{data.clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><span className="pill">Vista de consulta</span></div>}<div className="portal-hero"><div><span>SU SALDO FINANCIERO</span><strong>{fmt(line.outstanding,client.currency)}</strong><p>Al {date(asOf)} · {client.currency}</p></div><div><Wallet size={28}/><span>Línea disponible</span><strong>{fmt(line.available,client.currency)}</strong><small>Línea asignada {fmt(line.limit,client.currency)}</small></div></div><div className="metrics three"><Metric label="Pagos recibidos" value={fmt(sum(stats.map(s=>s.paid)),client.currency)} note="Cobros registrados hasta la fecha consultada"/><Metric label="Deuda vencida" value={fmt(sum(stats.map(s=>s.overdue)),client.currency)} note="Cuotas vencidas e interés moratorio"/><Metric label="Próximo vencimiento" value={date(stats.map(s=>s.nextDue).filter((s):s is string=>!!s).sort()[0]??null)} note="Primera cuota pendiente desde la consulta"/></div>{credits.map(c=>{const s=statement(c,asOf);return <section className="card portal-credit" key={c.id}><div className="card-head"><div><span className="eyebrow">{shortId(c.id)}</span><h2>{c.packageName}</h2><p>Compra {date(c.schedule.input.purchaseDate)} · TEA {rate(c.schedule.input.tea)} · TEQ {rate(c.schedule.teq)} · TEA moratoria {rate(c.schedule.input.mora??POLICY.mora)} · TED {rate(ted(c.schedule.input.mora??POLICY.mora))} · {c.schedule.input.months} meses</p></div><strong>{fmt(s.outstanding,c.currency)}<small className="block-note">Saldo financiero pendiente</small></strong></div><ScheduleTable schedule={c.schedule} rows={s.rows} currency={c.currency}/></section>;})}{!credits.length&&<Empty>No hay créditos originados a esta fecha.</Empty>}<div className="info-note"><HelpCircle size={18}/><p>Su línea aumenta al pagar la amortización de cada cuota. Los intereses de gracia ya capitalizados forman parte del saldo. Para registrar un cobro, comuníquese con su tienda.</p></div></>;
}
function Stores({data,refresh,notify}:{data:Data;refresh:()=>Promise<unknown>;notify:(s:string)=>void}){
  const [edit,setEdit]=useState<StoreRow|"new"|null>(null),s=edit&&edit!=="new"?edit:null;
  return <><PageTitle eyebrow="ADMINISTRACIÓN DEL SISTEMA" title="Tiendas en VidraCred" subtitle="Cada tienda tiene su propia cartera, catálogo, calendario y acceso."><button className="primary" onClick={()=>setEdit("new")}><Plus size={17}/>Nueva tienda</button></PageTitle><section className="card"><div className="table-wrap"><table><thead><tr><th>Tienda</th><th>RUC</th><th>Corte mensual</th><th>Vencimientos</th><th>Estado</th><th/></tr></thead><tbody>{data.stores.map(s=><tr key={s.id}><td><strong>{s.name}</strong><small>{s.business}</small></td><td className="mono">{s.ruc}</td><td>Día {s.cut_day}</td><td>Días {[s.pay_day,((s.pay_day+14)%30)+1].sort((a,b)=>a-b).join(" y ")}</td><td><span className={"badge "+(s.active?"pagada":"vencida")}>{s.active?"Activa":"Inactiva"}</span></td><td><button className="text-button" onClick={()=>setEdit(s)}>Editar<ChevronRight size={14}/></button></td></tr>)}</tbody></table></div></section>{edit&&<Modal title={s?"Editar tienda":"Registrar tienda y administrador"} onClose={()=>setEdit(null)}><EntityForm onClose={()=>setEdit(null)} onSave={async f=>{await api("stores",{...(s?{id:s.id}:{}),name:textValue(f,"name"),business:textValue(f,"business"),ruc:textValue(f,"ruc"),cutDay:Number(f.get("cutDay")),payDay:Number(f.get("payDay")),active:f.get("active")==="on",...(!s?{adminName:textValue(f,"adminName"),adminEmail:textValue(f,"adminEmail"),adminPassword:textValue(f,"adminPassword")}: {})});await refresh();notify("Tienda guardada.");}}>{err=><><Field label="Nombre comercial"><input required name="name" maxLength={120} defaultValue={s?.name}/></Field><div className="form-grid"><Field label="Giro"><input required name="business" maxLength={60} defaultValue={s?.business}/></Field><Field label="RUC" name="ruc" error={err}><input required name="ruc" pattern="[0-9]{11}" defaultValue={s?.ruc}/></Field><Field label="Día de corte" hint="1 a 31; si no existe, se usa el último día"><input required type="number" name="cutDay" min={1} max={31} defaultValue={s?.cut_day??25}/></Field><Field label="Primer día de pago" hint="1 a 30; el otro queda a 15 días comerciales"><input required type="number" name="payDay" min={1} max={30} defaultValue={s?.pay_day??5}/></Field></div><label className="checkbox"><input name="active" type="checkbox" defaultChecked={s?.active??true}/>Tienda activa</label>{!s&&<><h3>Administrador del negocio</h3><Field label="Nombre"><input name="adminName" required maxLength={120}/></Field><Field label="Correo de acceso"><input required type="email" name="adminEmail"/></Field><Field label="Contraseña" hint="Al menos 10 caracteres"><input required type="password" name="adminPassword" minLength={10} maxLength={128} autoComplete="new-password"/></Field></>}</>}</EntityForm></Modal>}</>;
}
export {Login,Dashboard,Clients,Packages,Purchase,Schedules,PaymentView,CutView,Portal,Stores};
